 auto budget=std::make_shared<PendingBudget>();Scheduler s(budget);auto a=request("A"),b=request("B",2,WorkKind::GPU,AppKind::IMAGE);
 value(s.submit(a),"accept A");value(s.submit(b),"accept B");
 for(const char*expected:{"A","B","A","B"}){auto w=value(s.next_ready(),"ready");require(w.request.request_id==expected,"A B A B fairness");require(s.stats().active_gpu==1,"one GPU");require(!s.next_ready(),"no GPU overlap");auto o=outcome(w);o.retired=false;require(!s.complete(o),"must retire before rotating");ok(s.complete(outcome(w)),"completion ACK retire");require(!s.complete(outcome(w)),"duplicate completion rejected");}
 require(value(s.status(a.request),"A status")==RequestStatus::COMPLETED,"A terminal");require(budget->used()==0,"all task tokens retired");
 auto c=request("CPU",2);auto src=std::make_shared<Source>(2);src->cpu_first=true;c.source=src;auto d=request("GPU",1);value(s.submit(c),"cpu source");value(s.submit(d),"GPU beside CPU");auto cpu=value(s.next_ready(),"CPU ready");require(cpu.kind==WorkKind::CPU,"CPU first");auto gpu=value(s.next_ready(),"GPU while CPU dependency blocked");require(gpu.request.request_id=="GPU","blocked successor does not own GPU");ok(s.complete(outcome(gpu)),"gpu complete");ok(s.complete(outcome(cpu)),"cpu complete");auto successor=value(s.next_ready(),"CPU successor");ok(s.complete(outcome(successor)),"successor complete");
 auto legacy=request("legacy",2,WorkKind::LEGACY_EXCLUSIVE);auto later=request("later",1);value(s.submit(legacy),"legacy");value(s.submit(later),"later");for(int i=0;i<2;i++){auto w=value(s.next_ready(),"legacy next");require(w.request.request_id=="legacy","opaque transaction never interleaved");require(!s.next_ready(),"opaque owns barrier");ok(s.complete(outcome(w)),"legacy drained");}auto last=value(s.next_ready(),"later after opaque");require(last.request.request_id=="later","barrier release");ok(s.complete(outcome(last)),"last");
 Scheduler lazy(std::make_shared<PendingBudget>());auto huge=request("huge",10000000);auto large=std::dynamic_pointer_cast<const Source>(huge.source);value(lazy.submit(huge),"compact large source");require(large->reads==1&&lazy.stats().pending==1,"one-item prefetch no10million materialization");ok(lazy.cancel(huge.request),"large queued cancel");
 std::puts("U09_SCHEDULER_FAIRNESS_CPU_DEPENDENCY_LEGACY_LAZY_PASS_NOT_BOARD");
